import { FUNCTION_WORDS_A21_ADDED, PRIMARY_ORDER_A21 } from './a21-language.js';
import { WORD_IDS_A21 } from './a21.word-ids.js';
import { A21_LESEN, A21_HOEREN } from './a21.exams.js';
import { A21_META } from './a21.meta.js';
import { VOCABULARY_A21_ADDITIONS } from './a21.vocabulary.js';

const EXAM_KEY = 'goethe_a2';

export const FUNCTION_WORDS = [...A12_FUNCTION_WORDS, ...FUNCTION_WORDS_A21_ADDED];
export const DIALOG_NAMES = ['Herr', 'Frau', 'Ana', 'Chakiri', 'Lena', 'Brandt', 'Tim', 'Berger', 'Jonas', 'Schulz', 'Sommer', 'Novak', 'Yilmaz', 'Wagner', 'Hoffmann', 'Krüger', 'Bremen', 'Köln', 'Marokko', 'Frankreich', 'Österreich'];

const inheritedWords = new Map([CURRICULUM_A11, CURRICULUM_A12].flatMap(c => c.lektionen.flatMap(l => l.wortfeld)).map(w => [w.de, w]));
function word(de, en, plural = null) {
  const article = /^(der|die|das) /.exec(de)?.[1] || null;
  return { de, word: article ? de.slice(article.length + 1) : de, article, plural,
    en, review: inheritedWords.has(de), wordId: inheritedWords.get(de)?.wordId || WORD_IDS_A21[article ? de.slice(article.length + 1) : de] || null };
}

function lesson(nr, data) {
  const primarySlug = PRIMARY_ORDER_A21[nr - 1];
  return { nr, id: `a2.1-l${String(nr).padStart(2, '0')}`, minutes: 15, examKey: EXAM_KEY,
    primarySlug, grammarSlugs: [primarySlug], links: { listeningExercise: null, readingOrder: null },
    practiceRule: { topics: [primarySlug], typedMin: 4 }, ...data,
    wortfeld: [...data.wortfeld, ...VOCABULARY_A21_ADDITIONS[nr - 1].map(w => ({ ...w, review: false }))] };
}

function dialogue(title, setting, speakers, lines) {
  return { title, setting, lines: lines.map(([de, en], i) => ({ speaker: speakers[i % 2], de, en })) };
}

function units(teil, id, stimulus, rows) {
  const listening = teil.startsWith('Hören');
  const kind = teil === 'Hören Teil 4' ? 'trueFalse' : ['Lesen Teil 4', 'Hören Teil 2'].includes(teil) ? 'match' : 'mc3';
  return { ...(listening ? { kind: 'exam' } : {}), teil, units: rows.map(([question, questionEn, options, key, explanationDe, explanationEn], i) => ({
    id: `${id}-u${i + 1}`, teil, kind, groupId: Array.isArray(stimulus) ? `${id}-${i + 1}` : id,
    [listening ? 'audioText' : 'text']: Array.isArray(stimulus) ? stimulus[i] : stimulus,
    question, questionEn, options, answer: options[key], explanationDe, explanationEn,
    ...(teil === 'Hören Teil 3' ? { pictures: options.map(option => ({ option, src: `/images/course/a21/${option}.svg`, alt: ({ regal: 'Bücher im Regal', tisch: 'Bücher auf dem Tisch', balkon: 'Bücher auf dem Balkon' })[option] })) } : {}),
  })) };
}

