      wortfeld: [word('die Tomate', 'tomato', 'Tomaten'), word('die Birne', 'pear', 'Birnen'), word('die Flasche', 'bottle', 'Flaschen'), word('das Öl', 'oil', 'Öle'), word('frisch', 'fresh'), word('der Käse', 'cheese', 'Käse'), word('der Salat', 'salad; lettuce', 'Salate'), word('das Brot', 'bread', 'Brote'), word('das Gemüse', 'vegetables', '—'), word('das Obst', 'fruit', '—'), word('das Kilo', 'kilogram', 'Kilos'), word('das Stück', 'piece', 'Stücke'), word('der Markt', 'market', 'Märkte'), word('die Kasse', 'checkout', 'Kassen'), word('der Preis', 'price', 'Preise'), word('rot', 'red'), word('gelb', 'yellow'), word('lecker', 'delicious')],
      dialog: dialogue('Obst und Gemüse am Markt', 'Ana kauft am Markt ein. Die Verkäuferin Frau Schulz siezt ihre Kundin.', ['Frau Schulz', 'Ana'], [
        ['Guten Morgen! Unser Obst und Gemüse ist heute frisch.', 'Good morning! Our fruit and vegetables are fresh today.'],
        ['Ich möchte die roten Tomaten. Ein Kilo, bitte.', 'I would like the red tomatoes. One kilogram, please.'],
        ['Gern. Möchten Sie auch einen frischen Salat?', 'Of course. Would you also like a fresh lettuce?'],
        ['Ja. Sind die gelben Birnen lecker?', 'Yes. Are the yellow pears tasty?'],
        ['Ja. Mein frischer Käse ist auch sehr gut.', 'Yes. My fresh cheese is very good too.'],
        ['Dann nehme ich ein Stück. Und die große Flasche Öl, bitte.', 'Then I’ll take a piece. And the large bottle of oil, please.'],
        ['Gern. Brauchen Sie auch ein frisches Brot?', 'Of course. Do you also need a fresh loaf of bread?'],
        ['Nein, ich brauche kein frisches Brot. Was kostet alles zusammen?', 'No, I don’t need a fresh loaf. How much is everything together?'],
        ['Der Preis ist zwölf Euro. Sie bezahlen dort an der Kasse.', 'The price is twelve euros. You pay at the checkout over there.'],
        ['Danke. Ich kaufe gern auf dem Markt ein.', 'Thank you. I like shopping at the market.'],
      ]),
      pretest: { promptDe: 'Bestellen Sie einen Salat und Tomaten.', promptEn: 'Order a lettuce and tomatoes.', model: 'Ich möchte einen frischen Salat und die roten Tomaten.', accepted: ['Ich möchte', 'Ich nehme'] },
      notice: { title: 'Adjektive nach einem Artikel', ruleSlug: 'adjective-endings-intro', bodyDe: 'Nach der/die/das im Nominativ steht -e; nach die/keine/meine im Plural -en: **die roten Tomaten**. Im Akkusativ maskulin steht -en: **einen frischen Salat**. Nach ein/kein/mein ohne Endung trägt das Adjektiv die Endung: **ein frisches Brot**, **kein frisches Brot**, **mein frischer Käse**. Vergleichen Sie die Endungen. Dativ folgt in Lektion 11. Ein Produkt fehlt: Das Brot fehlt.', bodyEn: 'After der/die/das in the nominative use -e; after die/keine/meine in the plural use -en: **die roten Tomaten**. Masculine accusative takes -en: **einen frischen Salat**. After ein/kein/mein without an ending, the adjective carries the ending: **ein frisches Brot**, **kein frisches Brot**, **mein frischer Käse**. Compare the endings. Dative adjectives follow in lesson 11. An item is missing: Das Brot fehlt.', examples: ['Ich möchte die roten Tomaten. Ein Kilo, bitte.', 'Gern. Möchten Sie auch einen frischen Salat?'] },
      phonetik: { focus: 'Unbetonte Endungen -e und -en', items: ['RO-te', 'RO-ten', 'FRI-schen'] },
      hoeren: units('Hören Teil 1', 'a21-l04-hoeren', 'Liebe Kunden, heute kostet das Kilo Tomaten zwei Euro. Das Kilo Birnen kostet drei Euro. Unser Brot kostet vier Euro. Die Angebote gelten heute bis sechs Uhr. Morgen öffnen wir um acht Uhr.', [
        ['Sie hören eine Durchsage im Supermarkt. Was kostet das Kilo Birnen?', 'You hear a supermarket announcement. How much is a kilogram of pears?', ['zwei Euro', 'drei Euro', 'vier Euro'], 1, 'Ein Kilo Birnen kostet drei Euro.', 'A kilogram of pears costs three euros.'],
        ['Wie lange gelten die Angebote heute?', 'Until when are today’s offers valid?', ['bis acht Uhr', 'bis vier Uhr', 'bis sechs Uhr'], 2, 'Die Angebote gelten bis sechs Uhr.', 'The offers last until six.'],
        ['Was kostet vier Euro?', 'What costs four euros?', ['das Brot', 'die Tomaten', 'die Birnen'], 0, 'Das Brot kostet vier Euro.', 'The bread costs four euros.'],
      ]),
      sprechen: { readAloud: [1, 3], open: { teil: 'Sprechen Teil 2', promptDe: 'Erzählen Sie von Ihren Einkäufen. Sprechen Sie über alle vier Punkte.', promptEn: 'Talk about your shopping. Cover all four points.', prompts: ['Wo kaufen Sie Lebensmittel?', 'Was kaufen Sie oft?', 'Markt oder Supermarkt?', 'Was ist teuer?'], hintWords: ['der Markt', 'frisch', 'der Preis'], anrede: 'Sie', missionOrder: null } },
      schreiben: { kind: 'mitteilung', textsorte: 'sms', taskKey: 'a21-l04', minWords: 20, maxWords: 30, taskDe: 'Sie sind auf dem Markt. Ihre Freundin Lena kocht heute. Schreiben Sie ihr eine SMS.', taskEn: 'You are at the market. Your friend Lena is cooking today. Send her a text message.', leitpunkte: ['Was Sie schon gekauft haben', 'Was heute fehlt', 'Frage: Was braucht Lena noch?'], sample: 'Hallo Lena, ich habe die roten Tomaten und den frischen Salat gekauft. Heute fehlt das Brot. Brauchst du noch Käse? Liebe Grüße, Ana' },
